function URLLoadTextDocs(entryNo)
{
    var str1 = theMenu.entry[entryNo].url.split('/');
    var item = (str1.length>1) ? str1[str1.length-1] : theMenu.entry[entryNo].url;
    parent.frame_content.location.href = item;
    parent.frame_content.location.reload();
}

function toggleChild(entryNo)
{
    for (level=theMenu.entry[entryNo].parent; level>-1; )
    {
        if ( theMenu.entry[level].isopen == false )
            eval(theMenu.toggle(level));
        level = theMenu.entry[level].parent;
    }
    highlightFocus(entryNo);
}
function highlightFocus(entryNo)
{
    var x = self.menu.document.links.length;
    var str1 = theMenu.entry[entryNo].url.split('/');
    var item = (str1.length>1) ? str1[str1.length-1] : theMenu.entry[entryNo].url;
    for ( xloc = 0; xloc<x; xloc++ )
    {
        if ( str1[str1.length-1]=='#')
            continue;
        var str = self.menu.document.links[xloc].href.split('/');
        if ( str[str.length-1]==item)
        {
            self.menu.document.links[xloc].focus();
            return ;
        }
    }
}
function loadDocs(type)
{
    var entryNo = (theMenu.selectedEntry==-1) ? (type=='next')?-1:0 : theMenu.entry[theMenu.selectedEntry].id;
    if ( (entryNo==theMenu.count && type=='next') || (entryNo==0 && type=='prev') )
        return ;
    eval(theMenu.itemClicked((type=='next')?++entryNo:--entryNo));
    //URLLoadTextDocs(entryNo);
    toggleChild(entryNo);
}
function highlightFirstItem() {
        var entryNo = 0;
        eval(theMenu.itemClicked(entryNo));
        toggleChild(entryNo);
}

function nextDocs()
{
    eval(loadDocs('next'));
}

function prevDocs()
{
    eval(loadDocs('prev'));
}
