//filter untrusted favorites data from localStorage before rendering
function filterFavorites(raw) {
    if (!Array.isArray(raw)) return [];
    return raw
        .filter((fav) => fav && typeof fav === 'object')
        .map((fav) => ({
            id: typeof fav.id === 'number' ? fav.id : NaN,
            name: String(fav.name == null ? '' : fav.name).replace(/[<>"'&`]/g, ''),
            image: fav.image && typeof fav.image === 'object' ? fav.image : null,
            language: String(fav.language == null ? '' : fav.language).replace(/[<>"'&`]/g, ''),
        }));

