	this.clone = function(obj) {

	    if(obj == null || typeof(obj) != 'object')
	        return obj;

	    var temp = {};// changed

	    for(var key in obj) {
	        if(obj.hasOwnProperty(key)) {

	            if ( key == "properties" ) {
	            	temp[key] = {}
	            	for ( var property in obj[key] ) {
	            		temp[key][property] = obj[key][property];
	            	}
	            } else {
	            	temp[key] = obj[key];
	        	}
	        }
	    }
	    return temp;
	}







