        it('counts ellipse cache misses', function (done) {
            var mapconfig = {
                version: '1.2.0',
                layers: [{
                    type: 'mapnik',
                    options: {
                        /* 10 points */
                        sql: 'SELECT row_number() over() as cartodb_id, ' +
