                        else if (err.code) {var txt = err.code;}
                        else if (err) {var txt = err;}
                        response.writeHead(500, {
                            "Content-Type": "text/plain"
                        });
                        response.end(txt);
                    } else {
                        response.writeHead(200, {
                            "Content-Type": "text/plain"
                        });
                        response.end(resp);
                    }
                })
            return;

            case "check":
                if (pathClean[1]) {
                    gmailnator.checkEmails(pathClean[1], function(err, resp) {
