import { useSelector, useDispatch } from "react-redux";
import { Button, Col, Container, Row } from "react-bootstrap";
import LoadingSpinner from "./LoadingSpinner";

import { getDriverBookingRide } from "../redux";
import FeedbackMessage from "./FeedbackMessage";
import dateFormat from "dateformat";
import { LinkContainer } from "react-router-bootstrap";

function ManageDriverBooking({ rideId }) {
  const { user: currentUser, isLoggedIn } = useSelector((state) => state.user);
  const { bookingStatusVariant } = useSelector((state) => state.global);
  const { isloadingDriverRideBookingList, driverRideBookingData } = useSelector(
    (state) => state.ride
  );

  const dispatch = useDispatch();

  useEffect(() => {
    if (isLoggedIn) {
      dispatch(getDriverBookingRide(currentUser.id, rideId));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <Container className="my-2">
      <hr className="w-75 mx-auto my-4" />

      <Row>
        <Col>
          <h1 className="text-info text-center fw-light">
            Manage your booking request(s)
          </h1>
        </Col>
      </Row>
      {isloadingDriverRideBookingList ? (
        <Row>
          <Col className="text-center">
            <LoadingSpinner />
          </Col>
        </Row>
      ) : driverRideBookingData.length > 0 ? (
        <Row>
          <Col>
            <Container>
              {driverRideBookingData.map((booking, index) => (
                <Row key={index} className="align-items-center my-2">
                  <Col xs="auto">
                    #{index + 1} | {dateFormat(booking.createdAt, "dd/mm/yyyy")}{" "}
                    |{" "}
                    <span className="text-success">{booking.seatsBooked}</span>{" "}
                    seat(s) booked by{" "}
                    <span className="text-success">
                      {booking.User.username}
                    </span>{" "}
                    |
                    {/* Passenger comment:{" "}
                  <i className="text-success">"{booking.commentPassenger}"</i>. */}{" "}
                    Status:{" "}
                    <span
                      className={`text-${bookingStatusVariant(
                        booking.BookingStatusId
                      )}`}
                    >
                      {booking.BookingStatus.name}
                    </span>
                  </Col>
                  <Col
                    xs={12}
                    sm="auto"
                    className="text-center mx-auto mx-lg-0"
                  >
                    <LinkContainer to={`/booking/${booking.id}`}>
                      <Button variant="success" className="rounded-0">
                        Manage
                      </Button>
                    </LinkContainer>
                  </Col>
                </Row>
              ))}
            </Container>
          </Col>
        </Row>
      ) : (
        <Row>
          <Col className="text-center">
            <p className="lead">
              You do not have any bookings for this ride yet
            </p>
          </Col>
        </Row>
      )}

      <FeedbackMessage />
    </Container>
  );
}

export default ManageDriverBooking;

const database = require('../database/db')
const newUser = require('../database/create-user')
const bcrypt = require('bcrypt')
const jwt = require('../controllers/jwt')


module.exports = {
    index(req, res) {
        return res.status(200).render('index.html')
    },

    async home(req, res) {
        const token = req.body.token || req.query.token || req.headers['x-access-token'] || req.headers.authorization || res.token//|| req.app.get('token')
        let userPayload = jwt.decode(token)
        const db = await database

        let user = await db.all(`SELECT name, user, photo, status FROM users WHERE id=${userPayload.id} AND user="${userPayload.user}";`)
        const users = await db.all(`SELECT name, user, photo, status FROM users WHERE user<>"${userPayload.user}";`)
        user = user[0]


        return res.status(200).render('home.html', { users, user })
    },

    async signup(req, res) {
        const data = req.body

        if (data.photo == '') {
            data.photo = './assets/padrao.png'//link de uma foto de perfil padrao
        }

        if (data.status == '') {
            data.status = "Hey there, I'm using BRO!"
        }

        try {
            const db = await database
            const verify = await db.all(`SELECT * FROM users WHERE user="${data.user}"`)


            if (verify.length > 0) {
                res.status(400).send(`ERRO! ${data.user} já existe!`)

            } else {
                let hash = bcrypt.hashSync(data.password, 3)
                let username = data.user.toLowerCase().replace(/ /g, '_')

                if (jwt.isUserValid(username)) {
                    await newUser(db, { name: data.name, user: username, password: <PASSWORD>, photo: data.photo, status: data.status })

                    let id = await db.all(`SELECT id FROM users WHERE user="${username}"`)
                    var token = jwt.generateToken({ user: username, id: id[0].id })

                    req.session.token = token
                    return res.status(200).redirect(`/home`)

                } else {
                    return res.status(400).send("ERRO! NOME DE USUARIO INVALIDO, USE APENAS [a-z] [0-9] _ E PERMITIDO 4-12 CARACTERES")
                }

            }
        } catch (error) {
            console.log(error)
            res.status(500).send('ERRO! NÃO FOI POSSÍVEL CADASTRAR USUÁRIO')
        }

    },

    async login(req, res) {
        const data = req.body

        try {
            const db = await database
            const login = await db.all(`SELECT * FROM users WHERE user="${data.user}"`) // AND password="${<PASSWORD>}";`)//user="${data.name}" FROM users WHERE password="${<PASSWORD>}";`)
            const userHash = login[0].password

            const isValid = bcrypt.compareSync(data.password, userHash)

            if (isValid) {
                let id = login[0].id
                let user = login[0].user

                let token = jwt.generateToken({ user: user, id: id })
                req.session.token = token
                //res.setHeader('x-access-token', token)
                return res.status(200).redirect(`/home`)

            } else {
                return res.status(403).send('DADOS NÃO CONFEREM! senha ou usuario incorreto')
            }
        } catch (error) {
            console.log(error)
            return res.status(500).send('FALHA AO CONSULTAR DADOS!')
        }


    },

    async search(req, res) {
        const data = req.body.data

        try {
            const db = await database
            const results = await db.all(`SELECT * FROM users WHERE name LIKE "%${data}%" OR user LIKE "%${data}%"`)
            const searchInfo = { "name": data, "len": results.length }

            if (searchInfo.len > 0) {
                return res.status(200).render("search-results.html", { results, searchInfo })

            } else {
                res.status(404).send(`<h1>Não existe "${searchInfo.name}" no banco de dados</h1>`)
            }
        } catch (error) {
            res.status(503).send("<h1>Houve um erro no banco de dados, tente novamente!</h1>")
        }

    },

    async update(req, res) {
        try {
            const id = res.userId
            const field = req.body.field
            const newValue = req.body.newValue

            const db = await database
            await db.all(`UPDATE users SET ${field} = "${newValue}" WHERE id = ${id}`)
        } catch (error) {
            return res.status(503).send(`NOT WAS POSSIBLE UPDATE ${field} WITH ${newValue}`)
        }
    },

    async user(req, res) {
        const id = res.userId
        const userName = res.userName

        const db = await database
        let user = await db.all(`SELECT name, user, photo, status FROM users WHERE id=${id} AND user="${userName}";`)
        user = user[0]

        return res.status(200).render("user.html", { user })
    }
}

