// Validate a redirect URL built from request data: either an absolute URL
// whose hostname is allowed, or a relative path (no hostname), before use.
function isSafeRedirectUrl(url) {
  try {
    if (url.charAt(0) !== '/') {
      var parsed = new URL(url);
      if (!config.allowedHosts ||
          config.allowedHosts.indexOf(parsed.hostname) === -1) {
        return false;
      }
    }
    if (url.indexOf('\\') >= 0 || url.indexOf('://') >= 0 && url.indexOf('https') !== 0) {
      return false;
    }
    return true;
  } catch (e) {
    return false;
  }
}

