const Product = require('../models/Product');
const User = require('../models/User');
const Category = require('../models/Category');
/**
 * GET /
 * Products page.
 */
exports.index = (req, res) => {
    Product
        .find({})
        .exec((err, products) => {
            if (err) return res.send(err);
            // this will log all of the users with each of their posts
            Category.find({})
                .exec((err, categories) => {
                    if (err) console.log(err);
                    // this will log all of the users with each of their posts
                    res.render('products/index', {
                        title: 'All Products',
                        products,
                        categories: JSON.stringify(categories),
                        importBtn: true,
                        controls: true,
                    });
                });
        });
};
/**
 * GET /
 * Edit Product page.
 */
exports.editProductPage = (req, res) => {
    const { productId } = req.params;
    Product
        .findById(productId)
        .populate('categories', '_id')
        .exec((err, product) => {
            if (err) return res.send(err);
            // this will log all of the users with each of their posts
            // product.categories.map(c => c._id);
            Category.find({})
                .exec((err, c) => {
                    if (err) console.log(err);
                    // this will log all of the users with each of their posts
                    const categories = c.map(e => ({
                        name: e.name,
                        _id: e._id.toString()
                    }));
                    product.categories = product.categories.map(c => c._id);
                    res.render('products/edit', {
                        title: 'Edit Product',
                        categories: JSON.parse(JSON.stringify(categories)),
                        productData: JSON.parse(JSON.stringify(product))
                    });
                });
        });
};

/**
 * GET /
 * Unpublish Product.
 */
exports.unpublishProduct = (req, res) => {
    const { productId } = req.params;
    Product.update({ _id: productId }, { $set: { published: false } }, (err) => {
        if (err) {
            console.error(err);
            req.flash('errors', 'Can not unpublish product.');
        } else {
            req.flash('success', { msg: 'Product has been unpublished.' });
        }

        res.redirect('/');
    });
};

/**
 * GET /
 * Publish Product.
 */
exports.publishProduct = (req, res) => {
    const { productId } = req.params;
    Product.update({ _id: productId }, { $set: { published: true } }, (err) => {
        if (err) {
            console.error(err);
            req.flash('errors', 'Can not publish product.');
        } else {
            req.flash('success', { msg: 'Product has been published.' });
        }
        res.redirect('/');
    });
};

/**
 * GET /
 * Save to list Product.
 */
exports.toggleSaved = (req, res) => {
    const { productId } = req.params;
    if (!req.user || !req.user._id) {
        req.flash('info', { msg: 'You need to authorize.' });
        return res.redirect('/');
    }

    User.findById(req.user._id)
        .select('savedProducts')
        .exec(function(err, object) {
            let json = JSON.parse(JSON.stringify(object.savedProducts));
            const savedProducts = new Set(json);
            if (savedProducts.has(productId)) {
                savedProducts.delete(productId);
            } else {
                savedProducts.add(productId);
            }
            object.savedProducts = [...savedProducts];
            object.save(function(err, model) {
                if (err) {
                    console.error(err);
                    req.flash('errors', 'Error.');
                } else {
                    req.flash('success', { msg: 'Success.' });
                }
                res.redirect('/');
            });
        });
};

/**
 * POST /
 * Save Product method.
 */
exports.editProduct = (req, res) => {
    const { body, user } = req;
    const { productId } = req.params;

    Product.findById(productId, (err, product) => {
        if (err) return res.sendStatus(500);
        if (product.creator.toString() !== user._id.toString()) {
            req.flash('errors', 'You do not have permission to edit this product');
            return res.redirect(`/products/${productId}`);
        }
        const data = {
            name: body.name,
            title: body.title,
            choice: (body.choice === 'on'),
            features: body.features,
            price: body.price,
            rating: body.rating,
            link: body.link,
            categories: body.categories,
            creator: user._id,
        };
        if (req.file && req.file.path) {
            data.image = req.file.path;
        }
        product.set(data);
        product.save((err, result) => {
            if (err) {
                req.flash('errors', err);
                return res.redirect(`/products/${productId}`);
            }
            // saved!
            req.flash('success', { msg: 'Product has been saved.' });
            return res.redirect('/my-products-page/');
        });
    });
};

/**
 * GET /
