exports.getAll = (req, res) => {
    const queries = {};
    for (const query in req.query) {
        if (req.query[query]) queries[query] = req.query[query];
    }
    Product
        .find(queries)
        .populate('categories', 'name')
        .select({
            name: 1,
            title: 1,
            rating: 1,
            price: 1,
            link: 1,
            imported: 1,
            createdAt: 1,
            categories: 1,
        })
        .exec((err, products) => {
            if (err) return res.send(err);
            // this will log all of the users with each of their posts
            res.send(products);
        });
};

/**
 * GET /
 * Product page.
 */
exports.product = (req, res) => {
    const { productId } = req.params;
    Product
        .findById(productId)
        .populate('categories', '_id')
        .exec((err, product) => {
            if (err) return res.send(err);
            // this will log all of the users with each of their posts
            // product.categories.map(c => c._id);
            Category.find({})
                .exec((err, categories) => {
                    if (err) console.log(err);
                    res.render('products/product-page', {
                        title: 'Product',
                        main: true,
                        product,
                        categories
                    });
                });
        });
};
/**
 * POST /
 * Delete Product.
 */
exports.delete = (req, res) => {
    const { body } = req;
    Product.deleteMany({
        _id: { $in: body.ids }
    })
        .exec((err, data) => {
            if (err) return res.send(500, err);
            // this will log all of the users with each of their posts
            res.sendStatus(200);
        });
};
/**
 * POST /
 * Import Product.
 */
exports.importProduct = (req, res) => {
    const { productId } = req.params;
    Product.update({ _id: productId }, { $set: { imported: true } }, (err) => {
        if (err) {
            console.error(err);
            res.sendStatus(500);
        } else {
            res.sendStatus(200);
        }
    });
};
/**
 * POST /
 * Export Product.
 */
exports.exportProduct = (req, res) => {
    const { productId } = req.params;
    Product.update({ _id: productId }, { $set: { imported: false } }, (err) => {
        if (err) {
            console.error(err);
            res.sendStatus(500);
        } else {
            res.sendStatus(200);
        }
    });
};

/**
 * GET /
 * Export Products.
 */
exports.exportProducts = (req, res) => {
    const { products } = req.body;
    if (!products) {
        // bad request!
        req.flash('error', { msg: 'Products not selected.' });
        return res.redirect('/products-page/');
    }

    Product.update({ _id: { $in: products } }, { $set: { imported: false } }, (err) => {
        if (err) {
            // error!
            console.error(err);
            req.flash('error', { msg: 'Error.' });
        } else {
            // saved!
            req.flash('success', { msg: 'Products are imported.' });
        }
        return res.redirect('/products-page/');
    });
};

