var express = require('express');
var router = express.Router();
var request = require('request');
var _ = require('lodash');
var geocode = require('geocoder');
var Promise = require('bluebird');

router.get('/health', function(req, res) {
	res.send('Good');
});

router.get('/', function(req, res) {
    var url = 'https://seeclickfix.com/api/v2/issues?place_url=santa-clara&state=CA&per_page=10&page=1';


    request(url, function(err, response, body) {
        if (err) {
            console.error(err);
        }
        var city = "santa-clara";
        var id = 1;
        var list = JSON.parse(body).issues;
        var metadata = JSON.parse(body).metadata;
        var per_page = metadata.pagination.per_page;
        var pages = metadata.pagination.pages;
        var lat = _.pluck(list, 'lat');
        var lng = _.pluck(list, 'lng');
        var summary = _.pluck(list, 'summary');
        var address = _.pluck(list, 'address');
        var start = 0;
        var next_page = 2;
        console.log('This is how many pages ', pages);
        if (id <= pages) {
            start = per_page * (id - 1);

        }
        if (id < pages) {
            next_page = (Number(id) + 1);
        }

        var title = city;
        var issues = pages * per_page;

        var getzips = function(lat, lng) {
            return new Promise(function(resolve, reject) {
                geocode.reverseGeocode(lat, lng, function(err, data) {
                    if (err) { reject(err); }
                    var zips = data.results[0].address_components;
                    var newzips = _.reduce(zips, function(all, item, index) {
                        if (item.types[0] == 'postal_code') {
                            all.push(item.short_name);
                        }
                        return all;
                    }, []);
                    resolve(newzips);
                });
            });
        };

        Promise.all(lat.map(function(_, index) {
                return getzips(lat[index], lng[index]);
            })).then(function(data) {
                var zips = _.union(_.flatten(data));
                return zips;
            })
            .then(function(zips) {

                res.render('index', {
                    title: title,
                    list: list,
                    lat: lat,
                    lng: lng,
                    summary: summary,
                    per_page: per_page,
                    pages: pages,
                    start: start,
                    city: city,
                    next_page: next_page,
                    address: address,
                    issues: issues,
                    zips: zips
                });
            });
    });
});

router.get('/:city', function(req, res) {
    var city = req.params.city;

    if (city == 'hampton') {
        res.redirect('/');
    } else {
        res.redirect('/' + city + '/1');
    }
});

router.get('/:city/:id', function(req, res) {
    var city = req.params.city;
    var id = req.params.id;
    if (city == 'hampton') {
        res.redirect('/');
    }
    var url = "https://seeclickfix.com/api/v2/issues?place_url=" + city + '&state=VA&per_page=10&page=' + id;

    request(url, function(err, response, body) {
        if (err) {
            console.error(err);
        }
        var list = JSON.parse(body).issues;
        var metadata = JSON.parse(body).metadata;
        var per_page = metadata.pagination.per_page;
        var pages = metadata.pagination.pages;
        var lat = _.pluck(list, 'lat');
        var lng = _.pluck(list, 'lng');
        var summary = _.pluck(list, 'summary');
        var address = _.pluck(list, 'address');
        var start = 0;
        var next_page = 2;
        console.log('This is how many pages ', pages);
        if (id <= pages) {
            start = per_page * (id - 1);

        }
        if (id < pages) {
            next_page = (Number(id) + 1);
        }

        if (city == 'newport-news') {
            title = 'newport news';
        } else if (city == 'virginia-beach') {
            title = 'virginia beach';
        } else if (city == 'hampton') {
            title = 'hampton';
        } else {
            title = city;
        }
        var issues = pages * per_page;

        var getzips = function(lat, lng) {
            return new Promise(function(resolve, reject) {
                geocode.reverseGeocode(lat, lng, function(err, data) {
                    if (err) { reject(err); }
                    var zips = data.results[0].address_components;
                    var newzips = _.reduce(zips, function(all, item, index) {
                        if (item.types[0] == 'postal_code') {
                            all.push(item.short_name);
                        }
                        return all;
                    }, []);
                    resolve(newzips);
                });
            });
        };

        Promise.all(lat.map(function(_, index) {
                return getzips(lat[index], lng[index]);
            })).then(function(data) {
                var zips = _.union(_.flatten(data));
                return zips;
            })
            .then(function(zips) {

                res.render('index', {
                    title: title,
                    list: list,
                    lat: lat,
                    lng: lng,
                    summary: summary,
                    per_page: per_page,
                    pages: pages,
                    start: start,
                    city: city,
                    next_page: next_page,
                    address: address,
                    issues: issues,
                    zips: zips
                });
            });
    });
});

router.post('/', function(req, res) {
    var city = req.body.city;
    var url = 'https://seeclickfix.com/api/v2/issues?place_url=' + city + '&state=VA'; //insert city in this link
    request(url, function(err, response, body) {
        if (err) {
            console.error(err);
        }
        var list = JSON.parse(body).issues;
        var lat = _.pluck(list, 'lat');
        var lng = _.pluck(list, 'lng');
        var summary = _.pluck(list, 'summary');
        res.render('index', { title: city, list: list, lat: lat, lng: lng, summary: summary });
    });


});

module.exports = router;

