const REDIRECT_WHITELIST = ['/']

const safeRedirect = (req, res, fallback) => {
  const referer = req.headers.referer
  if (typeof referer === 'string' && referer.length > 0 && REDIRECT_WHITELIST.indexOf(referer) >= 0) {
    res.redirect(referer)
  } else {
    res.redirect(fallback)
  }
}

if (errors) {
