  }).catch((err) => {
    logger.error({
      message: Errors.DB_ERROR,
      meta: { ...req.logMeta, error: err }
    });
    res.status(500).json(Errors.DB_ERROR);
  });
});

app.post('/devices/:deviceId/permissions', checkAuth, logRequest, (req, res) => {
