  }
  if (req.body.hasOwnProperty('parentalRestrictions')) {
    update.parentalRestrictions = req.body.parentalRestrictions;
  }
  if (req.body.hasOwnProperty('removeOwner')) {
    update.$pull = { owners: req.body.removeOwner };
