const adminRouter = require('./src/routes/admin')



//user routes
app.use('/', homeRouter)
//admin routes
app.use('/admin', adminRouter)


app.use((req,res)=>{
    res.render('404.ejs', {root: __dirname})
})


// Listen on port 5000
app.listen(port, () => console.log(`Listening on port ${port}`))

