var express = require('express');
var path = require('path');
var favicon = require('serve-favicon');
var logger = require('morgan');
var cookieParser = require('cookie-parser');
var bodyParser = require('body-parser');
var session = require('express-session');
var redisStore = require('connect-redis')(session);
var redis   = require("redis");
var client  = redis.createClient();

var env       = process.env.NODE_ENV || 'development';
var config    = require(path.join(__dirname, './config/config.json'))[env];

var routes = require('./routes/index');
var district = require('./routes/district');
var deputy = require('./routes/deputy');
var party = require('./routes/party');
var chamber = require('./routes/chamber');
var location = require('./routes/location');
var state = require('./routes/state');

var app = express();

// view engine setup
app.set('views', path.join(__dirname, 'views'));
app.set('view engine', 'ejs');

// uncomment after placing your favicon in /public
//app.use(favicon(path.join(__dirname, 'public', 'favicon.ico')));
app.use(logger('dev'));
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: false }));
app.use(cookieParser());
app.use(express.static(path.join(__dirname, '../public')));

if(env === 'production') {
  // Add client to config
  config.redis.client = client;
  app.use(session({
    secret: '4815162342',
    store: new redisStore(config.redis),
    saveUninitialized: false,
    resave: false
  }));
} else {
  app.use(session({
    secret: '4815162342',
    saveUninitialized: false,
    resave: false
  }));
}

// route middleware to make sure a user is logged in
function isLoggedIn(req, res, next) {

    // if user is authenticated in the session, carry on
    if (req.isAuthenticated())
        return next();

    // if they aren't redirect them to the home page
    res.send(401);
}

app.use('/', routes);
app.use('/district', district);
app.use('/deputy', deputy);
app.use('/party', party);
app.use('/chamber', chamber);
app.use('/state', state);
app.use('/location', location);

// catch 404 and forward to error handler
app.use(function(req, res, next) {
  var err = new Error('Not Found');
  err.status = 404;
  next(err);
});

// error handlers

// development error handler
// will print stacktrace
if (app.get('env') === 'development') {
  app.use(function(err, req, res, next) {
    res.status(err.status || 500);
    res.render('error', {
      message: err.message,
      error: err
    });
  });
}

// production error handler
// no stacktraces leaked to user
app.use(function(err, req, res, next) {
  console.log('Error');
  res.status(err.status || 500);
  res.render('error', {
    message: err.message,
    error: {}
  });
});


module.exports = app;

