		validatePassword: function(selector = '.validate-rif') {
			// const pattern = /^([VEJPGC]{1})([0-9]{7,9})$/g;
			const pattern = / ^(?=.*?[A-Z])(?=.*?[a-z])(?=.*?[0-9])(?=.*?[#?!@$ %^&*-]).{8,}$/gm;
			selector = getSelector(selector, 'validatePassword');
