import fse from 'fs-extra';
import addFile from './addFile';
import { isStaticRes } from "../util/util";
import getFiles from './getFiles';

const path = require('path');

/**
 * 删除一个文件的处理，按照如下规则
 * 1. isFileIgnore为true的直接忽略
 * 2. 如果删除的是一个目录，直接删除目标目录
 * 3. 删除的是图片文件： xx@3x.png，xx@2x.png，xx.png 
 *      如果删除的 xx@3x.png，删除目标文件；
 *              查找是否有 xx@2x.png，如果有，调用 addFile(filePath);
 *              如果没有，查找是否有 xx@1x.png，如果有，调用 addFile(filePath);
 *              如果没有，查找是否有 xx.png，如果有，调用 addFile(filePath);
 *      
 *      如果删除的 xx@2x.png，
 *              查找当前目录下是否有 xx@3x.png，如果有，直接返回。
 *              如果没有，删除目标文件，查找当前目录下是否有 xx@1x.png,如果有，调用 addFile(filePath)
 *              如果没有，删除目标文件，查找当前目录下是否有 xx.png,如果有，调用 addFile(filePath)
 * 
 *     如果删除的是 xx@1x.png
 *              查找当前目录下是否有 xx@2x.png 或 xx@3x.png ，如果有，直接返回。
 *              如果没有，删除目标文件，查找当前目录下是否有 xx.png,如果有，调用 addFile(filePath)
 * 
 *      如果删除的是 xx.png
 *              查找当前目录下是否有 xx@2x.png 或 xx@3x.png 或 xx@1x，如果有，直接返回。
 *              如果没有，删除目标文件
 * 
 * 4. 如果删除的 [fileName].wx.js，删除对应的目标文件（可能生成多个文件）; 看没有 [fileName].js; 调用 addFile(filePath) 
 * 5. 其他非js文件，直接删除
 * 6. 其他 js文件: [fileName].js，
 *      如果存在 [fileName].wx.js，直接返回。
 *      删除目标文件 
 *          [fileName].json, [fileName].js, 
 *          [fileName].wxml, [fileName].wxss, 
 *          [fileName].comp.js, [fileName]Template.wxml
 *          [fileName]ICNPxxx.js, [fileName]ICNPxxx.json
 *          [fileName]ICNPxxx.wxml, [fileName]ICNPxxx.wxss
 * 
 * @param filePath
 * @returns {Promise<void>}
 */

export default async function unlinkFile(filePath) {
    const { INPUT_DIR, OUT_DIR, configObj } = global.execArgs;

    const relativePath = filePath.replace(INPUT_DIR, '').replace(/\\/g, '/').substring(1);

    const srcPath = filePath;
    const targetPath = filePath.replace(INPUT_DIR, OUT_DIR);

    // 如果文件需要忽略， 则不处理
    if (typeof configObj.isFileIgnore === "function" && configObj.isFileIgnore(relativePath)) {
        return [];
    }

    if (isStaticRes(srcPath)) {
        if (srcPath.includes('@3x')) {
            //删除目标文件，查找是否存在 [fileName]@2x [fileName]@1x [fileName]
            await resolveStaticRes(srcPath, targetPath, 3);
        } else if (srcPath.includes('@2x')) {
            //查找是否有 [fileName]@3x,如果有返回；
            //删除目标文件，查找是否有 [fileName]@1x [fileName] 
            await resolveStaticRes(srcPath, targetPath, 2);
        } else if (srcPath.includes('@1x')) {
            //查找是否有 [fileName]@3x/查找是否有 [fileName]@2x,如果有返回；
            //删除目标文件，查找是否有 [fileName] 
            await resolveStaticRes(srcPath, targetPath, 1);
        } else {
            //查找是否有 [fileName]@3x/ [fileName]@2x /[fileName]@1x,如果有返回；
            //删除目标文件
            await resolveStaticRes(srcPath, targetPath, 0);
        }
    } else if (srcPath.endsWith('.js')) {

        let allFiles = [];
        if (srcPath.endsWith('.wx.js')) {
            //删除的是 .wx.js
            allFiles = await getFiles(targetPath, '.wx.js');
            await removeFiles(allFiles);
            if (fse.existsSync(srcPath.replace('.wx.js', '.js'))) {
                //是否存在同名 .js 文件
                await addFile(srcPath.replace('.wx.js', '.js'));
            }
        } else {
            //删除的是 .js
            const wxsrcPath = srcPath.replace('.js', '.wx.js');
            if (fse.existsSync(wxsrcPath)) {
                //如果存在同名的 .wx.js
                return [];
            } else {
                allFiles = await getFiles(targetPath, '.js');
                await removeFiles(allFiles);
            }
        }
    } else {
        await fse.remove(targetPath).catch(err => console.log(err));
    }
}

async function resolveStaticRes(srcPath, targetPath, num) {
    let imgIndex = num;
    let srcIndex = srcPath.lastIndexOf('@' + num + 'x'); //防止路径中出现 @nx
    if(srcIndex === -1) {
        srcIndex = srcPath.lastIndexOf('.');
    }
    if (num === 3 || num === 2 || num === 1) {
        let index = targetPath.lastIndexOf('@' + num + 'x');

        targetPath = targetPath.substring(0, index) + targetPath.substring(index + 3);
    }

    let leftArry = [];
    let rightArry = [];

    while (num < 3) {
        leftArry.push(++num);
    }
    while (num > 0) {
        rightArry.push(--num);
    }
    if (!existsHighPriority(srcPath, leftArry, srcIndex, imgIndex)) {
        //不存在更高优先级图片资源:删除图片资源，找更低优先级的图片资源
        await fse.remove(targetPath).catch(err => console.log(err));
        for (let i of rightArry) {
            let srcFile;
            if (i !== 0) {
                srcFile = srcPath.substring(0, srcIndex) + '@' + i + 'x' + srcPath.substring(srcIndex + 3);
            } else {
                srcFile = srcPath.substring(0, srcIndex) + srcPath.substring(srcIndex + 3);
            }
            if (fse.existsSync(srcFile)) {
                addFile(srcFile);
                return;
            }
        }
    } else {
        return;
    }
}


function existsHighPriority(srcPath, leftArry, srcIndex, imgIndex) {
    for (let i of leftArry) {
        let srcFile;
        if (i !== 0) {
            if(imgIndex === 0) {
                srcFile = srcPath.substring(0, srcIndex) + '@' + i + 'x' + srcPath.substring(srcIndex);
            }else{
                srcFile = srcPath.substring(0, srcIndex) + '@' + i + 'x' + srcPath.substring(srcIndex + 3);
            }

        } else {
            srcFile = srcPath.substring(0, srcIndex) + srcPath.substring(srcIndex + 3);
        }

        if (fse.existsSync(srcFile)) {
            return true;
        }

    }
    return false;

}


async function removeFiles(files) {
    //remove allFiles
    files.forEach(async (filePath) => {
        await fse.remove(filePath).catch((err) => {
            console.log(err);
        });
    });
}

/* global describe, beforeEach, test, expect */

const Url = require('../src/url');
const urls = require('./urls');

describe('Url', () => {

	// https://developer.mozilla.org/en-US/docs/Web/API/URLUtils
	var URLUtils = window.URL;


	function DOMUrl(href) {
		var a = document.createElement('a');
		a.href = href || location.toString();
		return a;
	}

	var cases = [
		//null,
		'about:blank',
		'http://rubaxa.org/',
		'ftp://foo:bar@rubaxa.org/',
		'http://rubaxa.org/',
		'https://rubaxa.org/',
		'http://rubaxa.org/foo',
		'http://rubaxa.org/foo/bar?query',
		'http://rubaxa.org/foo/bar?foo?bar',
		'http://rubaxa.org/foo/bar#foo?foo=1',
		'http://rubaxa.org///foo/////bar#foo?foo=1',
		// FIXME '#hash'
	];

	// URL vs. URLUtils
	test.each(cases)('URLUtils: %s', x => {
		var actual = new Url(x);
		var expected = new URLUtils(x);

		'href protocol host hostname port pathname search hash username password'.split(' ').forEach(function (attr) {
			expect(actual[attr]).toBe(expected[attr]); // "/" так надо для `about:blank`
		});
	});

	// URL vs. URLUtils(url, relative)
	test.each([
		'foo',
		'/foo',
		'?query',
		'#hash'
	])('URLUtils(url, relative): %s', x => {
		var actual = new Url(x, 'http://mail.ru/');
		var expected = new URLUtils(x || '', 'http://mail.ru/');

		'href protocol host hostname port pathname search hash username password'.split(' ').forEach(function (attr) {
			expect(actual[attr]).toBe(expected[attr]);
		});
	});

	// URL vs. <a/>
	test.each(cases)('<a/>: %s', x => {
		var actual = new Url(x);
		var expected = DOMUrl(x);

		'href protocol host hostname port pathname search hash username password'.split(' ').forEach(function (attr) {
			expect(actual[attr]).toBe(expected[attr]);
		});
	});

	test('without protocol', () => {
		var href = '//mail.ru/';

		// FIXME URL vs. URLUtils
		// expect(new Url(href).href).toBe(new URLUtils(href).href);
		// URL vs. <a/>
		expect(new Url(href).href).toBe(DOMUrl(href).href);
	});


	// Check urls
	test.each(urls)('Check url: %s', x => {
		// URL vs. URLUtils
		expect(new Url(x).href).toBe(new URLUtils(x).href);
		// URL vs. <a/>
		expect(new Url(x, location).href).toBe(DOMUrl(x).href);
	});


	test('/messages/(:type|folder/:id)', () => {
		var pattern = '/messages/(:type|folder/:id)';
		var matcher = Url.toMatcher(pattern);

		expect(matcher.source).toBe('^\\/messages\\/(?:(?:([^\\/]+))|folder\\/(?:([^\\/]+)))\\/*$');
		expect(matcher.keys).toEqual([
			{"name": "type", "optional": false},
			{"name": "id", "optional": false}
		]);

		// Тестируем `type`
		expect(Url.match(pattern)).toBe(null);
		expect(Url.match(pattern, '/messages/')).toEqual(null);
		expect(Url.match(pattern, '/messages/inbox')).toEqual({type: 'inbox'});
		expect(Url.match(pattern, '/messages/inbox/')).toEqual({type: 'inbox'});
		expect(Url.match(pattern, '/messages/inbox//')).toEqual({type: 'inbox'});
		expect(Url.match(pattern, '/messages/inbox/////')).toEqual({type: 'inbox'});

		// Тестируем `id`
		expect(Url.match(pattern, '/messages/folder/123')).toEqual({id: '123'});
		expect(Url.match(pattern, '/messages/folder/123/')).toEqual({id: '123'});
		expect(Url.match(pattern, '/messages/folder/123////')).toEqual({id: '123'});
	});


	test('/messages/(:type?|folder/:id)', () => {
		var pattern = '/messages/(:type?|folder/:id)';
		var matcher = Url.toMatcher(pattern);

		expect(matcher.source).toBe('^\\/messages\\/(?:(?:([^\\/]+))?|folder\\/(?:([^\\/]+)))\\/*$');
		expect(matcher.keys).toEqual([
			{"name": "type", "optional": true},
			{"name": "id", "optional": false}
		]);
		expect(Url.match(pattern, '/messages/')).toEqual({});
		expect(Url.match(pattern, '/messages/spam')).toEqual({type: 'spam'});
		expect(Url.match(pattern, '/messages/folder/123')).toEqual({id: '123'});
	});


	test('/:mode(foo|bar)', () => {
		var pattern = '/:mode(foo|bar)';
		var matcher = Url.toMatcher(pattern);

		expect(matcher.source).toBe('^\\/(?:(foo|bar))\\/*$');
		expect(matcher.keys).toEqual([{"name": "mode", "optional": false}]);
		expect(Url.match(pattern, '/')).toEqual(null);
		expect(Url.match(pattern, '/foo')).toEqual({mode: 'foo'});
		expect(Url.match(pattern, '/bar/')).toEqual({mode: 'bar'});
		expect(Url.match(pattern, '/baz/')).toEqual(null);
	});


	test('/:page/details/:id?', () => {
		var pattern = '/:page/details/:id?';
		var matcher = Url.toMatcher(pattern);

		expect(matcher.source).toBe('^\\/(?:([^\\/]+))\\/details(?:\\/([^\\/]+))?\\/*$');
		expect(matcher.keys).toEqual([{"name": "page", "optional": false}, {"name": "id", "optional": true}]);
		expect(Url.match(pattern, '/')).toEqual(null);
		expect(Url.match(pattern, '/foo/details/')).toEqual({page: 'foo'});
		expect(Url.match(pattern, '/foo/details/123')).toEqual({page: 'foo', id: '123'});
		expect(Url.match(pattern, '/details/123')).toEqual(null);
	});


	test('/:folder(foo|\\d+)?', () => {
		var pattern = '/:folder(foo|\\d+)?';
		var matcher = Url.toMatcher(pattern);

		expect(matcher.source).toBe('^(?:\\/(foo|\\d+))?\\/*$');
	});

	test('query methods', () => {
		var req = new Url('https://mail.ru/?foo&bar=baz');

		expect(req.query.foo).toBe('');
		expect(req.query.bar).toBe('baz');

		req.addToQuery({qux: 'Y'});
		expect(req.query.qux).toBe('Y');

		req.setQuery('qux=N&zzz');
		expect(req.query.qux).toBe('N');
		expect(req.query.zzz).toBe('');

		req.removeFromQuery('zzz');
		expect(req.query.zzz).toBe(void 0);

		req.removeFromQuery(['foo', 'bar']);
		expect(req.query.zzz).toBe(void 0);

		req.addToQuery({qux: null, 's"t"r': '<%^&>'});
		expect(req + '').toBe('https://mail.ru/?s%22t%22r=%3C%25%5E%26%3E');

		req.setQuery({}, true);
		expect(req + '').toBe('https://mail.ru/');
	});
});

