async function getBranchCommit(fullBranchName) {
  const commit = await vstsApi
    .gitApi()
    .getBranch(
      config.repoId,
      vstsHelper.getBranchNameWithoutRefsheadsPrefix(fullBranchName)
    );
  return commit.commit.commitId;
