export class PageModule extends Module {
  _page = 1;
  @observable state = {};
  // rootState = null;

  beforeResolve() {
    this.exit();
    this.state = {};
    this._page += 1;
  }
  afterResolve() {
    //
  }

  async wait(promise) {
    const beforePageId = this._page;
    let res;
    let err;
    try {
      res = await promise;
    } catch (error) {
      err = error;
    }
    const afterPageId = this._page;
    if (beforePageId !== afterPageId) throw new Err('page.cancel');
    if (err) throw err;
    return res;
  }

  getRootState() {
    if (this.rootState) return this.rootState;
    if (this.uapp && this.uapp.getRootState) return this.uapp.getRootState();
    if (this.app && this.app.getRootState) return this.app.getRootState();
    return { __page__: 123 };
  }

  getMeta() {
    const meta = (this.state && this.state.meta) || {};
    const title = (this.state.metas || [])
      .map((t) => t.title)
      .reverse()
      .join(' - ');
    return {
      ...meta,
      title,
    };
  }

  onExit(fn) {
    this.log.trace('onExit()');
    const { onExit = [] } = this.state;
    this.setState({
      onExit: [...onExit, fn],
    });
    return this;
  }

  async exit() {
    this.log.trace('exit()');
    const { onExit } = this.state;
    if (onExit && onExit.length) {
      await Bluebird.map(onExit, (fn) => fn());
      this.state.onExit = [];
    }
  }

  setState(state = {}) {
    this.log.trace('setState()');
    this.state = {
      ...this.state,
      ...state,
    };
    return this;
  }

  catchError(err) {
    this.log.error('error()', err);
    if (isDev) {
      if (this.app && this.app.onError) this.app.onError(err);
    }
    // if (isDev) {
    //   if (err.message) {
    //     console.error('Page.error:', err.message); // eslint-disable-line no-console
    //     if (err.stack) console.error(err.stack); // eslint-disable-line no-console
    //   } else {
    //     console.error(err); // eslint-disable-line no-console
    //   }
    // }
    // if (__CLIENT__ && this.uapp.checkVersion) {
    //   // / !!!!!!!!!!!!!
    //   this.uapp.checkVersion();
    // }
    throw err;
  }

  loading(...args) {
    this.log.trace('loading()');
    if (!args.length) return this.component('Loading...');
    return this.component(...args);
  }

  async next(next) {
    this.log.trace('next()');
    if (this.disabled) return this;
    try {
      const res = await next();
      return res;
    } catch (err) {
      return this.catchError(err);
    }
  }

  meta(meta) {
    this.log.trace('meta()', JSON.stringify(this.state.metas), meta);
    if (!this.state.metas) this.state.metas = [];
    this.state.metas.push(meta);
    this.state.meta = merge({}, ...this.state.metas);
    return this;
  }

  components = [];

  async component(...args) {
    this.log.trace('component()', args[0]);
    const result = await args[0];
    if (!result) throw new Err('!component');
    if (result.default) {
      args[0] = result.default; // eslint-disable-line no-param-reassign
    } else {
      args[0] = result; // eslint-disable-line no-param-reassign
    }
    // }
    if (args.length > 1) {
      this.components = args;
    } else {
      this.components = args[0]; // eslint-disable-line prefer-destructuring
    }
    this.log.trace('components()', this.components);
    return this;
  }

  redirect(...args) {
    const [redirect] = args;
    this.log.trace('redirect()', redirect);
    if (this.disabled) return this;
    this.state.redirect = args;
    return this;
  }

  renderComponent() {
    this.log.trace('renderComponent()', this.state);
    let Component;
    let props = {};
    if (Array.isArray(this.components)) {
      [Component, props] = this.components;
    } else {
      Component = this.components;
    }
    if (Array.isArray(this.components)) {
      return React.createElement(this.components[0], this.components[1] || {});
    }
    return React.createElement(Component, props);
  }

  render() {
    this.log.trace('renderRoot()');
    let children = this.renderComponent();
    if (typeof children === 'undefined') {
      if (isDev) {
        children = 'Page return empty result';
      } else {
        children = '';
      }
    }
    const { Provider } = this;
    if (!Provider) return children;
    const res = React.createElement(Provider, { app: this.app, page: this }, children);
    return res;
  }
}

export default PageModule;

import InputValidator from "../utility/InputValidator.js";

import Action from "./Action.js";
import TargetLock from "./TargetLock.js";

function ShipFledAction(environment, token, fromPosition)
{
   InputValidator.validateNotNull("environment", environment);
   InputValidator.validateNotNull("token", token);
   InputValidator.validateNotNull("fromPosition", fromPosition);

   this.environment = function()
   {
      return environment;
   };

   this.token = function()
   {
      return token;
   };

   this.fromPosition = function()
   {
      return fromPosition;
   };

   this.doIt = function()
   {
      LOGGER.trace("ShipFledAction.doIt() start");

      const tokens = [];

      if (token.isParent())
      {
         tokens.push(token.tokenFore());
         tokens.push(token.tokenAft());
      }
      else
      {
         tokens.push(token);
      }

      tokens.forEach(function(token)
      {
         const store = environment.store();
         TargetLock.removeAllTargetLocks(store, token);

         // Return the damage cards.
         if (token.isParent())
         {
            environment.discardAllDamage(token.tokenFore().damages());
            environment.discardAllDamage(token.tokenFore().criticalDamages());
            environment.discardAllDamage(token.tokenAft().damages());
            environment.discardAllDamage(token.tokenAft().criticalDamages());
         }
         else
         {
            environment.discardAllDamage(token.damages());
            environment.discardAllDamage(token.criticalDamages());
         }

         if (token)
         {
            environment.removeTouching(token);
            environment.removeToken(token);
         }
         store.dispatch(Action.setUserMessage("Ship fled the battlefield: " + token));
      });

      LOGGER.trace("ShipFledAction.doIt() end");
   };
}

export default ShipFledAction;

