function hxlog(obj, key, info, color, options = {}) {
  if (options.hasOwnProperty('begin') && options.begin === true) {
    console.group(`${info} :- ${key.replace(/\//g,'')} ${obj.replace(/\//g,'')} ■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■`)
  } else if (options.hasOwnProperty('end') && options.end === true) {
