        _.each(columnNames, function(columnName) {
            columnPlaceholders.push('?');
            params.push(columnName);
        });

        cql += columnPlaceholders.join(', ');
    } else {
        cql += '*';
    }

    cql += ' FROM ' + columnFamily + ' USING CONSISTENCY ' + consistency;

    if (fromKey) {
        cql += ' WHERE ? > ?';
