            placeholders.push('? = ?');
            q.parameters.push(key, value);
        }
    });

    q.query = 'UPDATE ' + cf + _createUsingClause(consistency, ttl);
    q.query += ' SET ' + placeholders.join(', ') + ' WHERE ' + rowKey + ' = ?';
