            } else {
                log().error({'err': err}, 'Error while describing cassandra keyspace.');
                callback({'code': 500, 'msg': 'Error while describing cassandra keyspace'});
            }
        } else {
            callback(null, definition);
        }
    });
};

/**
 * Close and re-open the cassandra connection pool.
 *
 * @param  {Function}   callback        Standard callback function
 * @param  {Object}     callback.err    An error that occurred, if any
 * @api private
 */
var _reloadPool = function(callback) {
    close(function() {
        // Initialize the pooled connections immediately.
        pool = _createPool(CONFIG);
        pool.connect(function(err) {
            if (err) {
                log().error({'err': err}, 'Error reloading cassandra pool');
                return callback({'code': 500, 'msg': 'Error reloading cassandra pool'});
            }

            return callback();
        });
    });
};

/**
 * Create a cassandra connection pool.
 *
 * @api private
 */
var _createPool = function(config) {
    var _pool = new Helenus.ConnectionPool(config);
    _pool.on('error', function(err) {
        log().error({err: err}, 'Error emmitted from the connection pool');
    });
    return _pool;
};

/**
 * Create a CQL "USING" clause with the given consistency and ttl.
 *
 * @param  {String}     [consistency]   The consistency value of the USING clause
 * @param  {Number}     [ttl]           The ttl of the USING clause
 * @return {String}                     A "USING" clause as per CQL syntax with a space before it, but no space after. If all parameters are unspecified, will simply return an empty string.
 * @api private
 */
var _createUsingClause = function(consistency, ttl) {
    var usingClauses = [];

    if (consistency) {
        usingClauses.push('CONSISTENCY ' + consistency);
    }

    if (ttl) {
        usingClauses.push('TTL ' + ttl);
    }

    // If we have at least one, return the using clause. The join will properly split them by ' AND ', as per CQL syntax.
    if (usingClauses.length > 0) {
        return ' USING ' + usingClauses.join(' AND ');
    }

    return '';
};

/**
 * Log a custom error with a stack trace so it can be diagnosed in the logs.
 *
 * @param  {String}     msg     The message of the error
 * @param  {Object}     data    Error data to log in the message. Any `err` key on this object will be overridden by the custom error.
 * @api private
 */
var _logCustomError = function(msg, data) {
    data = data || {};
    data.err = new Error(msg);
    log().error(data, msg);
};

const { Router } = require('express');
const asyncHandler = require('express-async-handler');
const bodyParser = require('body-parser').json();
const { parsePagedQuery } = require('../../middleware');
const Component = require('../../models/Component');

async function loadComponent(req, res, next) {
    const { id } = req.params;
    const component = await Component.findById(id);

    if (!component) {
        const error = new Error('Component is not found');
        error.statusCode = 404;
        throw error;
    }

    req.component = component;

    return next();
}

function checkReadAccess({iam}) {
    return async function (req, res, next) {
        const { user, component } = req;

        if (iam.hasOneOf({user, requiredPermissions: ['components.any.read']}) || component.access === 'public') {
            return next();
        }

        if (!component.owners.find(o => o.type === 'user' && o.id === user.sub)) {
            throw Object.assign(new Error('Not authorized'), {statusCode: 403});
        }

        return next();
    };
}

async function checkWriteAccess(req, res, next) {
    const { user, component } = req;

    if (user.isAdmin) {
        return next();
    }

    if (!component.owners.find(o => o.type === 'user' && o.id === user.sub)) {
        throw Object.assign(new Error('Not authorized'), {statusCode: 403});
    }

    return next();
}

module.exports = ({ iam }) => {
    const { can } = iam;
    const loadComp = asyncHandler(loadComponent);
    const canRead = asyncHandler(checkReadAccess({iam}));
    const canWrite = asyncHandler(checkWriteAccess);

    const GetList = asyncHandler(require('./GetList'));
    const Create = asyncHandler(require('./Create'));
    const GetOne = asyncHandler(require('./GetOne'));
    const PatchOne = asyncHandler(require('./PatchOne'));
    const Delete = asyncHandler(require('./Delete'));

    const router = Router();
    router.use(asyncHandler(iam.middleware));
    router.use((req, res, next) => {
        req.logger.trace({user: req.user}, 'Resolved IAM user');
        return next();
    });

    router.get('/', parsePagedQuery(), GetList);
    router.post('/', can('components.create'), bodyParser, Create);
    router.get('/:id', loadComp, canRead, GetOne);
    router.patch('/:id', can('components.update'), loadComp, canWrite, bodyParser, PatchOne);
    router.delete('/:id', can('components.delete'), loadComp, canWrite, Delete);

    return router;
};

import Mustache from 'mustache'
import Json from './Json'
import LoggerFactory from './LoggerFactory'
function truthy (val) {
  if (val == null || val.length === 0 || val === false) { return false }
  return true
}
function isInt (val) {
  return /^\d+?$/.test(val)
}
class MyContext extends Mustache.Context {
  constructor (value, parent, first, last) {
    super(value, parent)
    this._first = first
    this._last = last
  }

  lookup (name) {
    if (/-?last/.test(name)) {
      return this._last
    }
    if (/-?first/.test(name)) {
      return this._first
    }
        // match the dot, unless it is followed only by a number, than we guess its an array and
        // we will let the natural path happen.
    if (/.+?\.(?!\d+?$).+?$/.test(name)) {
      const filters = name.split(/(\-|\+|\.)/)
      let arr = super.lookup(filters.shift())
      if (!isIterable(arr)) {
        return arr
      }
            // Using a Set to prevent duplicates, this may be a mistake.
      const ret = new Set()
      FILTER: for (let v of arr) {
        for (let i = 0, l = filters.length; i < l; i += 2) {
          const pm = filters[i]
          const prop = filters[i + 1]
          if (pm == '+') {
            if (!truthy(v[prop])) { continue FILTER }
          } else if (pm === '-') {
            if (truthy(v[prop])) { continue FILTER }
          } else if (pm === '.' && prop) {
            if (v != null) { v = v[prop] }
          }
        }
        ret.add(v)
      }
      return Array.from(ret)
    }
    return super.lookup(name)
  }

  push (view, first, last) {
    return new MyContext(view, this, first, last)
  };
}

function isIterable (obj) {
    // checks for null and undefined
  if (obj == null) {
    return false
  }
    // Don't consider a string iterable.
  if (typeof obj === 'string') {
    return false
  }
  return typeof obj[Symbol.iterator] === 'function'
}

class MustacheWriter extends Mustache.Writer {
  renderSection (token, context, partials, originalTemplate) {
    let buffer = ''
    let value = context.lookup(token[1])

    if (!value) return

    if (isIterable(value)) {
      const itr = value[Symbol.iterator]()
      let first = itr.next()
      let isFirst = true
      while (!first.done) {
        const next = itr.next()
        if (first.value != null) {
          const ctx = context.push(first.value, isFirst, next.done)
          buffer += this.renderTokens(token[4], ctx, partials, originalTemplate)
        }
        isFirst = false
        first = next
      }
      return buffer
    } else if (typeof value === 'object' || typeof value === 'string' || typeof value === 'number') {
      buffer += this.renderTokens(token[4], context.push(value), partials, originalTemplate)
    } else if (typeof value === 'function') {
      if (typeof originalTemplate !== 'string') { throw new Error('Cannot use higher-order sections without the original template') }

            // Extract the portion of the original template that the section contains.
      value = value.call(context.view, originalTemplate.slice(token[3], token[5]), (template) => this.render(template, context, partials))

      if (value != null) { buffer += value }
    } else {
      buffer += this.renderTokens(token[4], context, partials, originalTemplate)
    }
    return buffer
  };
}

const Log = LoggerFactory.getLogger('Mustache')
export default ({
  compiler () {
    let defValue
    const partials = {}
    let partialProxy
    const cret = {

      withLoader (_loader) {
        const handler = {
          get (target, name) {
            if (name in target) return target[name]
            return (target[name] = _loader.getTemplate(name))
          }
        }
        partialProxy = function (name) {
          return _loader.getTemplate(name)
        }
        return cret
      },
      defaultValue (def) {
        defValue = def
        return cret
      },
      compile (template, file) {
        const writer = new MustacheWriter()

        return {
          execute (data) {
            try {
              data = JSON.parse(Json.pretty(data))
              return writer.render(template, new MyContext(data), partialProxy)
            } catch (e) {
              Log.trace(e)
              throw new Error(`Error invoking template ${file}`)
            }
          }
        }
      }
    }
    return cret
  }
})

