                }, { $group: { _id: 0, total: { $sum: {$floor: "$votes.claimable" } } } }
            ]).toArray(function (err, result) {
                if (err) {
                    console.log(err)
                    res.sendStatus(500)
                    return
                } else {
                    if (!result[0] || !result[0].total) {
                        res.send({ total: 0 })
                        return
                    }
                    res.send({ total: Math.round(1000 * result[0].total) / 1000 })
                }
            })
