                return
            }
            db.collection('contents').aggregate([
                { $unwind: "$votes" },
                {
                    $match: {
                        "votes.u": req.params.name,
                        "votes.claimed": { $exists: true }
                    }
                }, { $group: { _id: 0, total: { $sum: {$floor: "$votes.claimable" } } } }
            ]).toArray(function (err, result) {
                if (err) {
