    } else {
      gasScore = 100 - (HUMID_WEIGHT * 100);
    }
    airQuality = humidScore + gasScore;

    // Filter outlier values
    if(humidity > 100) humidity = NaN;
    if(temperature < -10 || temperature > 60) temperature = NaN;    
  } catch (error) {
    collectError = true;
    log.error(error);
  }

