      }
    }
  }
  /**
  * Process to reorganize and clean the database
  * @param {string} dir path where the database is located
  * @returns
  */
  vacum(dir) {
    if(dir) {
      if (!fs.statSync(dir).isDirectory()) {
        return
      }
