 */
exports.getJadeLoaderPluginMaybeWithPlugin = function(withPlugin, env) {
  const test = /\.jade$/
  var manifest = null
  if (withPlugin) {
    // var ExtractTextPlugin = require('extract-text-webpack-plugin')
