const applyOp = (op, left, right) => {
          switch (op) {
              case "+": return left + right;
              case "-": return left - right;
              case "*": return left * right;
              case "/": return right === 0 ? NaN : left / right;
              default: return right;
          }
      };

      /** Triggers the arithmetic operation. */
      const calulate = () => {
          if (calc === "") return;
          const tokens = calc.match(/(\d*\.?\d+|[+\-*/])/g) || [];
          let result = parseFloat(tokens[0]);
          let pendingOp = null;
          let pendingValue = null;
          for (let i = 1; i < tokens.length; i += 2) {
              const op = tokens[i];
              const value = parseFloat(tokens[i + 1]);
              if (pendingOp === null) {
                  pendingOp = op;
                  pendingValue = value;
              } else {
                  result = applyOp(pendingOp, result, value);
                  pendingOp = op;
                  pendingValue = value;
              }
          }
          if (pendingOp !== null) {
              result = applyOp(pendingOp, result, pendingValue);
          }
          if (!isFinite(result)) {
              setCalculator("0");
              return;
          }
          setCalculator(String(result));
      }

