const xssFilters = require("xss-filters");
const escapeString = (value) => {
  if (typeof value !== "string") return value;
  return value
    .replace(/&/g, "&amp;")
    .replace(/>/g, "&gt;")
    .replace(/</g, "&lt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;")
    .replace(/\//g, "&#x2F;")
    .replace(/\(/g, "&#x28;")
    .replace(/\)/g, "&#x29;");
};

