      expect(mappings).to.eql([
        { auth0: '_ICT Team Leaders', roles: ['testTymly_TeamLeader', 'expense_approvers'] },
        { auth0: '_ICT Devs', roles: ['testTymly_Devs'] }
      ])
    })
  })

  describe('remove mappings', () => {
