const run = (cmd, args = []) => {
    const process = spawn(cmd, args)
    let out = ''

    return new Bluebird((resolve, reject) => {
        process.stdout.on('data', data => {
            out += data.toString('utf8')
        })

        process.stderr.on('data', data => {
            out += data.toString('utf8')
        })

        process.on('error', err => {
            reject(err)
        })

        process.on('close', code => {
            resolve(out, code)
        })
    })
}

