  },
  storage: {
    storage: false,
    enable: function() {
      var storage,
        fail,
        uid;
      try {
        uid = new Date().toString();
        (storage = window.localStorage).setItem(uid, uid);
        fail = storage.getItem(uid) !== uid;
        storage.removeItem(uid);
        fail && (storage = false);
      } catch (e) {
      }
      if (!storage) {
        return false;
      } else {
        this.storage = storage;
        return true;
      }
    },
    clear: function() {
      if (this.storage) {
        this.storage.clear();
      }
    },
    set: function(uid, value) {
      if (this.storage) {
        var obj = {
          t: typeof value,
          v: value
        };
        if (obj.v instanceof Date) {
          obj.t = "date";
        }
        return this.storage.setItem(uid, JSON.stringify(obj));
      }
    },
    get: function(uid) {
      if (this.storage) {
        var val = this.storage.getItem(uid, 'json');
        val = JSON.parse(val);
        if (val) {
          switch (val.t) {
            case "date":
              return new Date(val.v);
            default :
              return val.v;
          }
        }
      }
    },
    remove: function(uid) {
      if (this.storage) {
        return this.storage.removeItem(uid)
      }
    }
  },
  webLayer: {
