  });

  const keys = [];
  Object.keys(scope)
    .sort()
    .forEach((name) => {
      keys.push(`${name}={{${scope[name]}}}`);
    });

  let shape = {};
  try {
    shape = argsShapeFromTemplate(code);
  } catch (e) {
    //
  }

  return {
    code,
    shape,
    args: keys,
  };
}

module.exports.transformSelection = transformSelection;

