function getCoords(elem) {
  var box = elem.getBoundingClientRect();
  var body = document.body;
  var docEl = document.documentElement;
  var scrollTop = window.pageYOffset || docEl.scrollTop || body.scrollTop;
  var scrollLeft = window.pageXOffset || docEl.scrollLeft || body.scrollLeft;
  var clientTop = docEl.clientTop || body.clientTop || 0;
  var clientLeft = docEl.clientLeft || body.clientLeft || 0;
  var top = box.top + scrollTop - clientTop;
  var left = box.left + scrollLeft - clientLeft;
  return { top: Math.round(top), left: Math.round(left) };
}

function initFunction() {
  var init = function (argument) {
    this.options = {
      draw: true,
      /**尽可能短的wid*/
      simpleId: true,
      ...argument,
    };
    this.lastClick = document.body;
    var that = this;
    /**点击其他地方时，清除*/
    document.addEventListener("mousedown", function (event) {
      that.lastClick = event.target;
      if (that.focusedElement !== that.lastClick) {
        init.prototype.clean();
      }
    });
  };
  return init;
}

function simpleFyId(wid) {
  if (!wid) {
    return wid;
  }
  var result = wid;
  // todo 递归二分法 衰减
  try {
    var classList = wid.split(".");
    var newQuery = classList
      .slice(0, Math.fround(classList.length / 2))
      .join(".");
    if (!newQuery) {
      return wid;
    }
    if (document.querySelector(newQuery) === document.querySelector(wid)) {
      result = newQuery;
    }
  } catch (e) {}
  return result;
}

export { simpleFyId, getCoords, initFunction };

