var crypto = require('crypto');
function secureRandom(){
	var bytes = crypto.randomBytes(4);
	var n = ( bytes[0] << 24 | bytes[1] << 16 | bytes[2] << 8 | bytes[3] ) >>> 0;
	return n / 4294967296;
}

