			else
				selectedRow = $("tr.selected",$table).length;
			if(selectedRow==0){
				$("div[data-scope]").addClass("btn-disable").removeClass("btn-normal");
				$("div[data-scope=all]").removeClass("btn-disable").addClass("btn-normal");
			}else if(selectedRow==1){
