$(document).ready(function () {

    // Click events
    var clickEvents = {
        // Open field window
        openFieldsWindow: function ($this) {
            jsPanel.create({
                id: 'fields-panel',
                container: 'body',
                theme: 'primary',
                boxShadow: 0,
                position: 'right-bottom',
                contentSize: '300 350',
                dragit: {
                    snap: true
                },
                headerTitle: 'Available Fields',
                content: loadTemplate('fields-html'),
                callback: function () {
                    $this.addClass("disabled");

                    // Draggable fields
                    $('.draggable-element').draggable({
                        helper: 'clone'
                    });
                },
                onclosed: function () {
                    $this.removeClass("disabled");
                }
            });
        },
        // Open studio window
        openStudioWindow: function ($this) {
            $('.bbs-field-selectors>li').removeClass("active");
            $this.parent("li").addClass("active");

            var selector = '.bbcc-form',
                exclude = ['.col-*', '.row'];

            if ($('#studio-panel').length !== 0) {
                // Init CSS studio
                cssStudio.init(selector, {
                    cssOutputSelector: '#bbcc-form-style',
                    parentSelector: '#form-builder-rows'
                });
                return;
            }

            jsPanel.create({
                id: 'studio-panel',
                container: 'body',
                theme: 'primary',
                boxShadow: 0,
                position: 'right-bottom',
                contentSize: $(window).width() + ' 250',
                dragit: {
                    snap: true
                },
                headerTitle: 'Styling',
                content: '<div id="bb-css-studio" class="bb-css-studio no-active"></div>',
                callback: function () {
                    // Init CSS studio
                    cssStudio.init(selector, {
                        cssOutputSelector: '#bbcc-form-style',
                        parentSelector: '#form-builder-rows'
                    });
                },
                onclosed: function () {}
            });
