    stopServer() {
        this._server.close();
    }

    _setupServer() {
        this._app.set('port', this._listeningPort);
    }

    _setupRoutes() {
        this._app.get('/', (req, res) => {
            res.send('Hello World!');
        });
    }
}

module.exports = HttpServer;

