const axios = require("axios")

module.exports = {
	name: "price",
	description: "Gets price info for an item",
	async execute(message, args) {
		// Take in Item Name from Arguments and convert to item ID

		try {
			const queryFuzzWork = await axios.get(
				"https://www.fuzzwork.co.uk/api/typeid.php?typename=" + args.join(" ")
			)
			const itemTypeId = queryFuzzWork.data.typeID
			const getJitaPriceData = await axios.get(
				"https://api.evemarketer.com/ec/marketstat/json?typeid=" +
				itemTypeId +
				"&usesystem=30000142"
			)
			const getAmarrPriceData = await axios.get(
				"https://api.evemarketer.com/ec/marketstat/json?typeid=" +
				itemTypeId +
				"&usesystem=30002187"
			)
			const getJitaPrice = getJitaPriceData.data[0].sell.min
			const getJitaBuyPrice = getJitaPriceData.data[0].buy.max
			const getAmarrPrice = getAmarrPriceData.data[0].sell.min
			const getAmarrBuyPrice = getAmarrPriceData.data[0].buy.max
			message.reply(
				`\n**Jita Sell Price:** ${addCommasToPrice(
					getJitaPrice
				)}\n**Jita Buy Price:** ${addCommasToPrice(
					getJitaBuyPrice
				)}\n**Amarr Sell Price: **${addCommasToPrice(
					getAmarrPrice
				)}\n**Amarr Buy Price: ** ${addCommasToPrice(getAmarrBuyPrice)}`
			)
		} catch (error) {
			console.log(error)
			message.reply("Error, bug Alch to look at the logs")
		}
	},
}

const addCommasToPrice = (input) => {
	return input.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",")
}

