    // Clicks events are on the start block, even if it was a shadow.
    Blockly.Events.fire(
        new Blockly.Events.Ui(this.startBlock_, 'click', undefined, undefined));
  }
  this.bringBlockToFront_();
  Blockly.Events.setGroup(false);
