      report: {
          model: 'report'
      },

      testName: 'string',

      name: 'string',
      status: 'string'
  },

  getDistinctNames: function(cb) {
    Author.native(function(err, collection) {
        collection.distinct('name', function(err, result) {
            if (err) console.log(err);
            else cb(result);
        });
    });
  },
};

