     */
    $(document).on("click", ".icon-to-end", function(e) {
        playNext();
        playerStatus = "playing";
    });


    /**
     * play previous song in songslist
     */
    $(document).on("click", ".icon-to-start", function(e) {
        playNext('backward');
        playerStatus = "playing";
